    enonce: "a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">9a + 2b = 102</span> و <span dir=\"ltr\" class=\"expr\">ab = 60</span> جد العددين a و b علما أنّ الفرق بينهما يساوي 4",
    correction: [{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 4</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 4</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">9(b + 4) + 2b = 102</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">9b + 36 + 2b = 102</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">11b + 36 = 102</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">11b = 102 - 36</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 66 : 11 = 6</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 4 = 10</span>"}],
