    correction: [{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">6(4a + 7b) - 4(a + 3b) = 24a + 42b - 4a - 12b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">24a + 42b - 4a - 12b = 24a - 4a + 42b - 12b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">24a + 42b - 4a - 12b = 20a + 30b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">20a + 30b = 5(4a + 6b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">5(4a + 6b) = 5 × 208</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 1040</span>"}],
